/// How to fetch/play one item. Given to an external backend (Android) and
/// consumed by the native backend internally.
#[typeshare]
#[derive(Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct MediaSource {
    pub key: QueueKey,
    pub track: TrackSummary,
    /// `file://` for downloads (and, for a backend without the
    /// `core_stream` capability, cached streams); otherwise either
    /// `hocket-stream://<token>` — an opaque, expiring capability the
    /// backend reads through the core's stream reader (open at an offset,
    /// read, close; no credentials involved) — or, for a backend without
    /// that capability, the server's `https://` stream URL (auth in query).
    pub url: String,
    pub headers: HashMap<String, String>,
    pub mime_type: Option<String>,
    /// Gain to apply in dB after ReplayGain/normalisation. External backends apply this.
    pub gain_db: f64,
    pub transcoded: bool,
    /// Every byte is on this device when the source is resolved (a
    /// download, or a complete stream-cache entry, whatever the URL):
    /// playing it needs no network. A streamed source may become local
    /// while it plays (the queue's `offline` state shows it).
    #[serde(default)]
    pub local: bool,
}

/// A URL with its query string (where Subsonic carries the auth token) and
/// fragment removed, for logs.
pub fn redact_url(url: &str) -> String {
    let end = url.find(['?', '#']).unwrap_or(url.len());
    url[..end].to_string()
}

impl std::fmt::Debug for MediaSource {
    /// The stream URL is logged without its query string: it carries the
    /// auth token and salt.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("MediaSource")
            .field("key", &self.key)
            .field("track", &self.track)
            .field("url", &redact_url(&self.url))
            .field("headers", &self.headers.keys().collect::<Vec<_>>())
            .field("mime_type", &self.mime_type)
            .field("gain_db", &self.gain_db)
            .field("transcoded", &self.transcoded)
            .finish()
    }
}

/// Commands the core sends to an external playback backend.
#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", tag = "type", content = "data")]
pub enum BackendCommand {
    /// Replace what is loaded. `next` is the gapless follow-up to preload.
    Load {
        source: MediaSource,
        next: Option<MediaSource>,
        position_ms: Ms,
        play: bool,
    },
    /// Update only the preloaded follow-up.
    SetNext {
        next: Option<MediaSource>,
    },
    Play,
    Pause,
    Stop,
    Seek {
        position_ms: Ms,
    },
    /// The in-player gain (0–1, amplitude). With a system volume this is
    /// only the sleep fade; otherwise it also carries the user volume.
    SetVolume {
        volume: f64,
    },
    /// Set the platform's own media volume (Android's music stream): the
    /// slider position 0–1 and mute. Sent only to a backend that reports
    /// [`BackendReport::SystemVolume`].
    SetSystemVolume {
        volume: f64,
        muted: bool,
    },
    /// Handoff pre-buffering: fetch but don't play; discarded on timeout.
    PreBuffer {
        source: MediaSource,
        position_ms: Ms,
    },
    DiscardPreBuffer,
    SetGapless {
        enabled: bool,
    },
    /// Load a song into the preview player (a second output). The main item
    /// stays loaded. `position_ms` is where the preview starts.
    PreviewLoad {
        source: MediaSource,
        position_ms: Ms,
    },
    PreviewPlay,
    PreviewPause,
    PreviewSeek {
        position_ms: Ms,
    },
    /// Unload the preview player. The main item is untouched.
    PreviewStop,
}

/// What an external backend reports back.
#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", tag = "type", content = "data")]
pub enum BackendReport {
    Ready {
        key: QueueKey,
        duration_ms: Option<Ms>,
    },
    Playing {
        key: QueueKey,
        position_ms: Ms,
    },
    Paused {
        key: QueueKey,
        position_ms: Ms,
    },
    Buffering {
        key: QueueKey,
        buffering: bool,
    },
    /// Called at least every 1000 ms while playing and on every discontinuity.
    Position {
        key: QueueKey,
        position_ms: Ms,
    },
    /// Natural end; the backend has already transitioned to `next` if given.
    Ended {
        key: QueueKey,
    },
    /// Transitioned to the preloaded item (gapless).
    TransitionedToNext {
        key: QueueKey,
    },
    Error {
        key: QueueKey,
        message: String,
        fatal: bool,
    },
    PreBufferReady {
        key: QueueKey,
    },
    AudioFocusLost {
        transient: bool,
    },
    OutputDevicesChanged {
        devices: Vec<OutputDevice>,
    },
    /// The platform's media volume (0–1) or mute changed, by whatever means
    /// (hardware keys, another app, a headset). A backend that sends this
    /// owns the device's volume: the core mirrors it instead of applying
    /// its own gain, and drives it with [`BackendCommand::SetSystemVolume`].
    /// Sent once at start and on every change.
    SystemVolume {
        volume: f64,
        muted: bool,
    },
    /// The preview player knows the song's duration.
    PreviewReady {
        duration_ms: Option<Ms>,
    },
    /// Where the preview is. `playing` is false while it is paused.
    PreviewProgress {
        position_ms: Ms,
        playing: bool,
    },
    /// The preview played to the end.
    PreviewEnded,
    /// The preview player could not load or play the song.
    PreviewFailed,
    /// The preview player lost the output (another app took audio focus).
    /// The main session must not be resumed into that.
    PreviewInterrupted,
}

