/// A secret supplied by the platform (a server password). Serialises as a
/// plain string; its `Debug` output is redacted so a command logged at
/// `trace` never carries the password.
#[typeshare]
#[derive(Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Secret(pub String);

impl Secret {
    /// Expose the secret. Callers must not copy it into logs or long-lived
    /// storage.
    pub fn expose(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Debug for Secret {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("Secret(<redacted>)")
    }
}

impl From<String> for Secret {
    fn from(s: String) -> Self {
        Secret(s)
    }
}

impl From<&str> for Secret {
    fn from(s: &str) -> Self {
        Secret(s.to_string())
    }
}

#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", tag = "type", content = "data")]
pub enum Command {
    // -- lifecycle --------------------------------------------------------
    /// First command after construction. Loads persisted state, starts subsystems.
    /// Emits [`Event::Started`] exactly once per core (a repeated `Start` behaves
    /// like `RequestSnapshot`).
    Start,
    /// Flush everything and stop. The process may exit afterwards. Platforms
    /// that need to know when the flush is done use `Core::shutdown()`.
    Shutdown,
    /// Re-emit every `*Changed` event with current state (UI (re)attach),
    /// preceded by [`Event::Snapshot`]. Never emits a second `Started`, so
    /// platforms can key one-time work (credential replay) on `Started`.
    RequestSnapshot,
    SetNetworkState {
        state: NetworkState,
    },
    /// App visibility for renderer throttling and prefetch pausing.
    SetVisibility {
        visible: bool,
        focused: bool,
    },
    /// The device's own power-save state (Android Power Saver, a laptop on
    /// battery). While `battery.autoEngage` is on it engages battery saver at
    /// `battery.autoLevel`; the level itself is the `battery.level` setting.
    SetPowerSave {
        enabled: bool,
    },

    // -- servers ----------------------------------------------------------
    /// `url` must be `http(s)://` with a host and no embedded credentials.
    /// Naming a server that is already persisted (same url + username)
    /// installs it immediately from the stored capabilities (so downloads
    /// play offline) and probes in the background; a new server is only
    /// installed once the probe accepts the credentials.
    AddServer {
        url: String,
        username: String,
        password: Secret,
        name: Option<String>,
    },
    RemoveServer {
        server_id: ServerId,
    },
    ProbeServer {
        server_id: ServerId,
    },
    /// `full` forces a reconcile that catches deletions.
    SyncLibrary {
        server_id: ServerId,
        full: bool,
    },
    SetTranscodingProfile {
        network_id: Option<String>,
        profile: TranscodingProfile,
    },

    // -- transport --------------------------------------------------------
    Play,
    Pause,
    TogglePlay,
    Stop,
    Next,
    Previous,
    /// Back a track, never restarting this one however far in it is (the
    /// skip swipe): Previous without its restart, the queue deciding (it
    /// restarts the track only when there is nothing before it).
    PreviousTrack,
    SeekTo {
        position_ms: Ms,
    },
    SeekBy {
        delta_ms: i32,
    },
    /// Set the volume of the device playing (this one when nobody is), and
    /// unmute it.
    SetVolume {
        volume: f64,
    },
    /// Mute or unmute the device playing (this one when nobody is). Each
    /// device remembers its own level across a mute.
    SetMuted {
        muted: bool,
    },

    // -- preview ----------------------------------------------------------
    /// Play a song beside the queue, starting about 30% in. Pauses playback
    /// on this device and restores it afterwards; a Connect peer is left
    /// playing. Never written to the queue, play history, scrobbles or the
    /// resume position.
    PreviewStart {
        track_id: TrackId,
    },
    /// Pause or resume the preview that is already open.
    PreviewToggle,
    /// Seek the preview. The position is clamped to the song.
    PreviewSeek {
        position_ms: Ms,
    },
    /// Stop the preview and, on this device, resume what was playing.
    PreviewStop,

    // -- queue ------------------------------------------------------------
    PlayContext {
        args: PlayContextArgs,
    },
    /// Play an ad-hoc list (search results, a selection).
    PlayTracks {
        server_id: ServerId,
        track_ids: Vec<TrackId>,
        start_index: u32,
        label: String,
        shuffle: bool,
        /// Audio position to start the chosen track at. Part of the same
        /// command so a following seek cannot land on the previous song.
        #[serde(default)]
        start_position_ms: Ms,
    },
    /// Directly after the current entry (ahead of the group), in the group when the Queue
    /// section setting is on. `keys` names queue entries to put there instead of new copies:
    /// one ahead of the pointer moves, one behind it (or the current one) is copied.
    PlayNext {
        server_id: ServerId,
        track_ids: Vec<TrackId>,
        #[serde(default)]
        keys: Vec<QueueKey>,
    },
    /// At the end of the "Next in queue" group. `keys` as for `PlayNext`.
    AddToQueue {
        server_id: ServerId,
        track_ids: Vec<TrackId>,
        #[serde(default)]
        keys: Vec<QueueKey>,
    },
    /// At the end of the whole list, outside the group. `keys` as for `PlayNext`.
    PlayLater {
        server_id: ServerId,
        track_ids: Vec<TrackId>,
        #[serde(default)]
        keys: Vec<QueueKey>,
    },
    /// Put songs directly after `after` (the current entry's key for the top of the list), in
    /// the "Next in queue" group or out of it: a library drop onto a queue slot. Placed like a
    /// `MoveQueueItem` drop (nothing above the current entry or into history; an `inGroup` drop
    /// past the group's end lands at its end, an out-of-group one inside it just after it).
    /// `keys` as for `PlayNext`: one ahead of the pointer moves, one behind it is copied.
    InsertTracks {
        server_id: ServerId,
        track_ids: Vec<TrackId>,
        #[serde(default)]
        keys: Vec<QueueKey>,
        after: QueueKey,
        in_group: bool,
    },
    /// Move the pointer to this entry. Nothing in the list changes: the entries jumped over
    /// end up behind the pointer.
    JumpToQueueItem {
        key: QueueKey,
    },
    RemoveQueueItems {
        keys: Vec<QueueKey>,
    },
    /// Drag an entry ahead of the pointer to directly after `after` (the current entry's key
    /// for the top of the list), in the group or out of it. Nothing moves above the current
    /// entry or into history. An `inGroup` drop past the group's end lands at its end; an
    /// out-of-group drop inside the group lands just after it.
    MoveQueueItem {
        key: QueueKey,
        after: QueueKey,
        in_group: bool,
    },
    ClearQueue,
    /// Remove the "Next in queue" group's entries.
    ClearQueueGroup,
    /// Send the "Next in queue" group's songs to the stash and remove them from the queue.
    StashQueueGroup,
    SetShuffle {
        enabled: bool,
    },
    SetRepeat {
        mode: RepeatMode,
    },
    SetAutoplay {
        enabled: bool,
    },
    /// Mark the current item unplayable on this device and move on.
    SkipUnavailable {
        key: QueueKey,
    },

    // -- saved queues -----------------------------------------------------
    RestoreSavedQueue {
        id: String,
    },
    PinSavedQueue {
        id: String,
        pinned: bool,
    },
    DeleteSavedQueue {
        id: String,
    },
    /// Rename a queue. `saved_queue_id: None` renames the queue that is
    /// playing (its context label); otherwise the saved queue with that ID.
    /// A blank label is ignored.
    RenameQueue {
        saved_queue_id: Option<String>,
        label: String,
    },
    SaveQueueAsPlaylist {
        saved_queue_id: Option<String>,
        name: String,
    },
    SetSavedQueueCap {
        cap: u32,
    },

    // -- stash ------------------------------------------------------------
    /// Stash songs (added at the end). Songs already in the stash are skipped.
    StashAdd {
        track_ids: Vec<TrackId>,
    },
    /// Take entries out of the stash. Toasts with an Undo.
    StashRemove {
        entry_ids: Vec<String>,
    },
    /// Move an entry to `toIndex` in the stash as listed.
    StashMove {
        entry_id: String,
        to_index: u32,
    },
    /// Empty the stash. Toasts with an Undo.
    StashClear,
    /// Continue an album at its saved track and position. Falls back to the start when
    /// there is nothing to resume (or the feature is off).
    ResumeAlbum {
        album_id: AlbumId,
    },
    /// Forget an album's resume point (Start over).
    ClearAlbumResume {
        album_id: AlbumId,
    },
    /// Put removed entries back where they were (the Undo of remove and clear).
    StashRestore {
        entry_ids: Vec<String>,
    },

    // -- snooze -----------------------------------------------------------
    /// Leave songs out of shuffle, playlists, artist play and autoplay for `duration`.
    /// Goes through global undo.
    Snooze {
        track_ids: Vec<TrackId>,
        duration: SnoozeFor,
    },
    /// Snooze songs until a chosen moment (the menu's Custom row). Goes through global undo.
    SnoozeUntil {
        track_ids: Vec<TrackId>,
        until: EpochMs,
    },
    /// Bring snoozed songs back. Goes through global undo.
    Unsnooze {
        track_ids: Vec<TrackId>,
    },

    // -- undo -------------------------------------------------------------
    Undo,
    Redo,
    /// Undo a specific entry from the history sheet.
    UndoEntry {
        id: String,
    },
    RestoreSelection,

    // -- library mutations (all through the outbox, all undoable) ---------
    SetRating {
        targets: Vec<RatingTarget>,
        rating: u32,
    },
    SetLoved {
        targets: Vec<RatingTarget>,
        loved: bool,
    },
    SetArtistLoved {
        artist_id: ArtistId,
        loved: bool,
    },
    CreatePlaylist {
        server_id: ServerId,
        name: String,
        track_ids: Vec<TrackId>,
    },
    DeletePlaylist {
        playlist_id: PlaylistId,
    },
    RenamePlaylist {
        playlist_id: PlaylistId,
        name: String,
        comment: Option<String>,
        public: Option<bool>,
    },
    PlaylistAdd {
        playlist_id: PlaylistId,
        track_ids: Vec<TrackId>,
        at_index: Option<u32>,
    },
    /// Indices into the playlist's current order.
    PlaylistRemove {
        playlist_id: PlaylistId,
        indices: Vec<u32>,
    },
    PlaylistMove {
        playlist_id: PlaylistId,
        from_index: u32,
        to_index: u32,
    },
    /// Marks a played track on the server (`scrobble submission=true`) — used only by the
    /// core's own scrobbler. The variant stays on the wire for API stability, but it is
    /// only acted on with the `sim` feature (it bypasses the threshold, session dedupe
    /// and the scrobble setting); a release core ignores it.
    Scrobble {
        track_id: TrackId,
        played_at: EpochMs,
        submission: bool,
    },

    // -- downloads --------------------------------------------------------
    Pin {
        target: PinTarget,
        transcode: bool,
    },
    Unpin {
        target: PinTarget,
    },
    ClearStreamCache,
    /// The album primer: the album page has been open a moment, or the
    /// pointer rests on its play button. The core resolves the album's
    /// first track and asks the device that owns playback (this one when
    /// nobody else does) to fetch its first seconds into the stream cache,
    /// so pressing play starts from disk. The owner decides with its own
    /// state: only on an unmetered network, not in battery saver, never on
    /// the coordinator; deduplicated and rate-limited. Fire and forget.
    PrimeAlbum {
        album_id: AlbumId,
    },
    /// [`Command::PrimeAlbum`] for one track (a hovered track row).
    PrimeTrack {
        track_id: TrackId,
    },
    /// What the platform's playback backend can do. `core_stream`: it reads
    /// `hocket-stream://<token>` media sources through the core's stream
    /// reader (`stream_open`/`stream_read`/`stream_close` on the core
    /// handle) instead of fetching URLs itself. Default false for an
    /// external backend (sources then carry the server URL as before); the
    /// native backend always reads through the core.
    SetBackendCapabilities {
        core_stream: bool,
    },
    SetStorageWarnThreshold {
        bytes: Option<f64>,
    },

    // -- jobs and problems ------------------------------------------------
    CancelJob {
        id: JobId,
    },
    RetryJob {
        id: JobId,
    },
    PauseJob {
        id: JobId,
    },
    ResumeJob {
        id: JobId,
    },
    RetryProblem {
        id: String,
    },
    DismissProblem {
        id: String,
    },
    DismissAllProblems,

    // -- filters and autoplay --------------------------------------------
    SaveFilter {
        filter: Filter,
    },
    DeleteFilter {
        id: FilterId,
    },
    /// Native API, behind the capability flag.
    CreateSmartPlaylist {
        server_id: ServerId,
        filter: Filter,
        name: String,
    },
    CreateStaticPlaylistFromFilter {
        server_id: ServerId,
        filter: Filter,
        name: String,
    },
    /// Writes the NSP document to `path` (or returns it via [`Event::NspExported`]).
    ExportNsp {
        filter: Filter,
        path: Option<String>,
    },
    SetAutoplaySettings {
        settings: AutoplaySettings,
    },

    // -- lyrics -----------------------------------------------------------
    SetLyricsOffset {
        track_id: TrackId,
        offset_ms: i32,
    },
    SetExternalLyricsEnabled {
        enabled: bool,
    },
    FetchLyrics {
        track_id: TrackId,
    },

    // -- settings ---------------------------------------------------------
    SetSetting {
        key: String,
        value: String,
    },
    ResetSetting {
        key: String,
    },
    SetSettingsSync {
        enabled: bool,
    },
    ExportConfig {
        include_secrets: bool,
    },
    /// The platform's diagnostics bundle, answering
    /// [`Event::DiagnosticsRequested`]. Sent to the device that asked.
    AnswerDiagnosticsRequest {
        request_id: String,
        text: String,
    },
    /// Save a report on the hosted coordinator: the user's `note`, the
    /// platform's diagnostics `bundle` (what Save to file would write) and
    /// `attachments`. Needs the leave the coordinator sent with the latest
    /// room diagnostics ([`RoomDiagnosticsStatus::report_upload`]). Runs in
    /// the background, resuming across restarts; progress goes out as
    /// [`Event::ReportUploadChanged`]. One at a time: ignored (with a
    /// warning in the log) while another is uploading, so platforms hide the
    /// action then. See `docs/reports.md`.
    StartReportUpload {
        note: String,
        bundle: String,
        attachments: Vec<ReportAttachment>,
    },
    /// Try the failed report upload again, from where it stopped.
    RetryReportUpload,
    /// Forget the report upload (cancelling it if it is still running) and
    /// delete what the core staged for it.
    DismissReportUpload,
    /// Import a config document (`ExportConfig` output). Account-synced
    /// settings it changes are broadcast to the other devices like a local
    /// edit. Device-local settings (audio output, transcoding, storage,
    /// `connect.*`, display theme/accent, battery, …) describe the device the
    /// document came from and are left alone unless `include_device_local`
    /// is set (default false; older callers may omit it).
    ImportConfig {
        document: String,
        #[serde(default)]
        include_device_local: bool,
    },

    // -- audio ------------------------------------------------------------
    SetAudioSettings {
        settings: AudioSettings,
    },
    SetOutputDevice {
        id: Option<String>,
    },
    RefreshOutputDevices,

    // -- connect ----------------------------------------------------------
    SetCoordinatorUrl {
        url: Option<String>,
    },
    ConnectCoordinator,
    DisconnectCoordinator,
    SetLanDiscovery {
        enabled: bool,
    },
    /// Opens the picker: targets start pre-buffering.
    OpenHandoffPicker,
    CloseHandoffPicker,
    HandoffTo {
        device_id: DeviceId,
    },
    /// Headphones (Bluetooth or wired) connected to this device. With headphone
    /// handoff on (beta, `connect.headphone_handoff`), pulls playback here
    /// from a device that plays or just paused.
    HeadphonesConnected {
        name: Option<String>,
    },
    /// Accept the dormant resume offer and take transport here.
    ResumeHere,
    DismissResumeOffer,

    // -- sleep timer ------------------------------------------------------
    SetSleepTimer {
        timer: Option<SleepTimer>,
    },

    // -- from the platform ------------------------------------------------
    /// Reports from an external playback backend.
    BackendReport {
        report: BackendReport,
    },
    /// OS media session button/command (headset, lockscreen, MPRIS, SMTC).
    MediaSessionCommand {
        action: MediaSessionAction,
        value: Option<f64>,
    },
    /// Run a registry action against a target. The core validates applicability.
    RunAction {
        action_id: String,
        target: ActionTarget,
    },
    /// Custom shortcut binding (desktop). `shortcut` is a normalised chord string.
    SetShortcut {
        action_id: String,
        shortcut: Option<String>,
    },
    /// Choose-and-order customisation for a surface (`contextMenu`, `sidebar`, `mediaSession`).
    SetActionOrder {
        surface: String,
        action_ids: Vec<String>,
    },
    /// The UI's current multi-selection, so commands can snapshot it.
    SetSelection {
        target: ActionTarget,
    },
    /// Marks a saved queue / track as interacted with (for LRU).
    Touch {
        target: ActionTarget,
    },
}

impl Command {
    /// The variant name as it appears on the wire (`"addServer"`), for logs
    /// that must never carry the payload.
    pub fn kind(&self) -> String {
        serde_json::to_value(self)
            .ok()
            .and_then(|v| v.get("type").and_then(|t| t.as_str()).map(str::to_string))
            .unwrap_or_else(|| "?".into())
    }
}

