/// What an `Event::PlayerNotice` is about, stable across releases and
/// languages (the `message` text is neither).
#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum PlayerNoticeCode {
    /// Offline: tracks neither downloaded nor fully cached are skipped.
    OfflineSkipping,
    /// Offline, and nothing left in the queue plays here: playback stopped.
    NothingAvailableOffline,
    /// No server connection to stream from.
    NoServer,
    /// A non-fatal playback problem (`detail`: the backend's message).
    PlaybackProblem,
    /// A track failed to play and was skipped (`detail`: its title).
    CouldNotPlaySkipped,
    /// Stopped after several unplayable tracks in a row (`detail`: the last title).
    CouldNotPlayStopped,
    /// Autoplay was asked for more and found nothing to add.
    AutoplayFoundNothing,
}

/// Where one source of a [`RoomDiagnosticsStatus`] stands.
#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum DiagnosticsSourceState {
    /// Asked, nothing arrived yet.
    Waiting,
    /// Some of its parts arrived.
    Receiving,
    /// Its whole bundle arrived.
    Received,
    /// It said no (`reason`: why, in its words).
    Declined,
    /// The collection ended with only some of its parts.
    Incomplete,
    /// The collection ended without a word from it.
    NoAnswer,
}

/// One source of a room diagnostics collection: another device, or the coordinator.
#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct DiagnosticsSourceStatus {
    pub id: String,
    pub name: String,
    pub state: DiagnosticsSourceState,
    pub parts_received: u32,
    /// Parts it said it sends (0 until the first arrives).
    pub parts: u32,
    /// Text received so far.
    pub bytes: u32,
    /// Why it declined.
    pub reason: Option<String>,
}

/// Why a `Query::RoomDiagnostics` collected nothing.
#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum RoomDiagnosticsUnavailable {
    /// Developer mode is off on this device.
    DeveloperModeOff,
    /// Connect is not running.
    NotConnected,
}

/// How a `Query::RoomDiagnostics` collection is going ([`Event::RoomDiagnosticsChanged`]).
#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct RoomDiagnosticsStatus {
    pub request_id: String,
    /// The query has answered: nothing more arrives for this request.
    pub done: bool,
    pub elapsed_ms: f64,
    /// Set when nothing was asked (and `done`).
    pub unavailable: Option<RoomDiagnosticsUnavailable>,
    /// The room answered (and named the devices it asked).
    pub room_answered: bool,
    /// The room answered but asked nobody, in its words (asked again within
    /// 10 s of the last request: nobody else answers then, the coordinator
    /// included). Only seen with no earlier collection to fall back on: with
    /// one, the query answers with that one (text and status) instead.
    pub room_declined: Option<String>,
    /// The hosted coordinator's answer. It answers ahead of the room, so once
    /// `room_answered` is set and this is still unset, the room has no
    /// coordinator (a device hosts it) or one too old to answer.
    pub coordinator: Option<DiagnosticsSourceStatus>,
    /// The coordinator sent its process log, not only its version (it does
    /// for the accounts its operator named with `--diagnostics-user`).
    pub coordinator_log: bool,
    /// The other devices the room asked, in its order.
    pub devices: Vec<DiagnosticsSourceStatus>,
    /// The coordinator lets this account save reports there, and its leave
    /// is still good: offer [`Command::StartReportUpload`]. Only ever set by
    /// a coordinator that answered this collection.
    #[serde(default)]
    pub report_upload: bool,
}

/// A file going up with a report ([`Command::StartReportUpload`]).
#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct ReportAttachment {
    /// A file the core can read, as it is sent (platforms resize screenshots
    /// and strip their metadata first; recordings go as they are).
    pub path: String,
    pub kind: ReportAttachmentKind,
    /// The platform made this copy for the upload: the core deletes it once
    /// the upload is done or dismissed.
    #[serde(default)]
    pub delete_after: bool,
}

#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum ReportAttachmentKind {
    /// A JPEG or PNG image. At most 5 per report.
    Screenshot,
    /// A screen recording (MP4, WebM, MOV, MKV). At most 1 per report.
    Recording,
}

#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum ReportUploadState {
    Uploading,
    Done,
    Failed,
}

/// Why a report upload failed.
#[typeshare]
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum ReportUploadError {
    /// No leave from the coordinator (or it ran out, or the coordinator
    /// refused it): open diagnostics again while connected to it.
    NotAllowed,
    /// An attachment could not be read (or there are too many).
    Unreadable,
    /// Over what the coordinator takes (per file, per report or in total).
    TooLarge,
    /// The coordinator could not be reached, or the connection broke.
    Network,
    /// The coordinator answered with an error.
    Server,
}

/// Where the report upload stands ([`Event::ReportUploadChanged`],
/// `Query::ReportUpload`).
#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct ReportUploadStatus {
    pub state: ReportUploadState,
    pub sent_bytes: f64,
    pub total_bytes: f64,
    /// The coordinator's id for it (`R-20261101-7k3f`), once it made one.
    pub report_id: Option<String>,
    pub error: Option<ReportUploadError>,
    /// More about `error`, in English, for logs and developers.
    pub error_detail: Option<String>,
    /// Epoch ms the user sent it.
    pub started_at: f64,
}

#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", tag = "type", content = "data")]
pub enum Event {
    /// Emitted exactly once per core, when `Start` completes. Platforms key
    /// one-time work (credential replay, first-run setup) on this.
    Started {
        snapshot: Snapshot,
    },
    /// Emitted by `RequestSnapshot` (and by anything else that re-emits the
    /// whole state, such as `RemoveServer`) ahead of the `*Changed` replay.
    /// Same payload as `Started`, never confused with it.
    Snapshot {
        snapshot: Snapshot,
    },
    ServersChanged {
        servers: Vec<ServerInfo>,
    },
    SyncProgress {
        progress: SyncProgress,
    },
    /// Mirror tables changed; UIs should refetch visible queries. Empty = everything.
    /// `artistTopSongs` (with the artist ids) means a cached `Query::ArtistTopSongs`
    /// answer was refreshed in the background and now differs.
    LibraryChanged {
        server_id: ServerId,
        tables: Vec<String>,
        ids: Vec<String>,
    },
    SearchResults {
        results: SearchResults,
    },
    /// Ratings or loves changed: set here (including undo and the rating →
    /// love bridge) or, with `from_device`, on another signed-in device and
    /// relayed through Connect. The mirror already holds these values, so
    /// UIs patch every copy of the item they show (rows, detail headers,
    /// search results, menus) in place. Followed by a `LibraryChanged` for
    /// list refetches and, when the item is queued, by `NowPlayingChanged` /
    /// `QueueChanged` / `MediaSession`. A library sync that picks up changes
    /// made elsewhere reports them with `LibraryChanged` only.
    LibraryItemsChanged {
        server_id: ServerId,
        items: Vec<LibraryItemState>,
        /// The device the change came from; `None` for this one.
        #[serde(default)]
        from_device: Option<DeviceId>,
    },
    /// A playlist changed (tracks added, removed or moved, renamed, created
    /// or deleted), here or, with `from_device`, on another signed-in device.
    /// `playlist` is the mirror's row now; `None` when it was deleted.
    /// Screens showing it (its detail page, playlist lists and pickers)
    /// refetch its tracks. Followed by a `LibraryChanged`.
    PlaylistChanged {
        server_id: ServerId,
        playlist_id: PlaylistId,
        playlist: Option<Playlist>,
        #[serde(default)]
        from_device: Option<DeviceId>,
    },

    SessionChanged {
        document: SessionDocument,
    },
    QueueChanged {
        queue: QueueView,
    },
    /// Sent when something a receiver can't extrapolate changed: play state,
    /// a seek or a position that strayed from the stamp, buffering, volume,
    /// the lease owner. Never for position progress alone, nor for a lease
    /// renewal or `played_ms` alone (those ride along with the next one).
    TransportChanged {
        transport: TransportState,
    },
    /// The song preview opened, moved, paused or closed (`None`).
    PreviewChanged {
        preview: Option<PreviewState>,
    },
    /// The item now playing (or `None` when stopped), with a resolved track.
    NowPlayingChanged {
        entry: Option<QueueEntry>,
    },
    SavedQueuesChanged {
        queues: Vec<SavedQueue>,
    },
    /// The stash changed (here or on another device): the whole list, in order.
    StashChanged {
        items: Vec<StashItem>,
    },
    /// Snoozes changed (here or on another device): the songs still snoozed.
    SnoozesChanged {
        items: Vec<SnoozeItem>,
    },
    /// Albums that currently offer resume. Empty when the feature is off.
    AlbumResumesChanged {
        points: Vec<AlbumResumePoint>,
    },
    UndoChanged {
        state: UndoState,
    },
    Toast {
        toast: Toast,
    },
    /// Inline player-bar line for a non-fatal playback issue ("Couldn't play X, skipped").
    /// `message` is the core's English text; platforms that show their own
    /// (localised) text match on `code` and fill in `detail`. All `None`
    /// clears the line.
    PlayerNotice {
        message: Option<String>,
        #[serde(default)]
        code: Option<PlayerNoticeCode>,
        /// The variable part of the notice: the track's title for
        /// `couldNotPlaySkipped` / `couldNotPlayStopped`, the backend's
        /// message for `playbackProblem`; `None` for the others.
        #[serde(default)]
        detail: Option<String>,
    },

    JobsChanged {
        jobs: Vec<Job>,
    },
    ProblemsChanged {
        problems: Vec<Problem>,
    },

    ConnectionChanged {
        state: ConnectionState,
    },
    /// The network the platform last reported with `SetNetworkState`
    /// (`Snapshot.network`): emitted whenever it changes and in every
    /// replay. `None` until the platform first reports one.
    NetworkChanged {
        network: Option<NetworkState>,
    },
    /// Battery saver as it is engaged now (`Snapshot.batterySaver`): emitted
    /// whenever it changes and in every replay.
    BatterySaverChanged {
        saver: BatterySaver,
    },
    DevicesChanged {
        devices: Vec<DeviceInfo>,
    },
    HandoffPickerChanged {
        open: bool,
        targets: Vec<DeviceInfo>,
    },
    ResumeOfferChanged {
        offer: Option<ResumeOffer>,
    },

    LyricsChanged {
        track_id: TrackId,
        lyrics: Option<Lyrics>,
    },
    PinsChanged {
        pins: Vec<Pin>,
    },
    StorageChanged {
        storage: StorageSummary,
    },
    FiltersChanged {
        filters: Vec<Filter>,
    },
    SettingChanged {
        setting: Setting,
    },
    AudioSettingsChanged {
        settings: AudioSettings,
    },
    OutputDevicesChanged {
        devices: Vec<OutputDevice>,
    },
    SleepTimerChanged {
        timer: Option<SleepTimer>,
    },
    ShortcutsChanged {
        shortcuts: Vec<Shortcut>,
    },
    ActionsChanged {
        surface: String,
    },
    NspExported {
        filter_id: FilterId,
        document: String,
        path: Option<String>,
    },
    ConfigExported {
        document: String,
    },
    /// Another device in the Connect room asks for this device's diagnostics
    /// (developer mode is on here). Build the bundle the diagnostics page
    /// would save and answer with [`Command::AnswerDiagnosticsRequest`];
    /// without an answer within 10 s the core sends its own diagnostics and
    /// log instead.
    DiagnosticsRequested {
        request_id: String,
        from_device: String,
    },
    /// Progress of a `Query::RoomDiagnostics`: when it starts, as answers
    /// arrive, and once more (`done`) when the query answers.
    RoomDiagnosticsChanged {
        status: RoomDiagnosticsStatus,
    },
    /// The report upload moved on: started, progressed (at most about four
    /// times a second), finished, failed, or was dismissed (`None`).
    ReportUploadChanged {
        status: Option<ReportUploadStatus>,
    },

    /// Drive an external backend (Android). Not emitted in native mode.
    Backend {
        command: BackendCommand,
    },
    /// Drive the OS media session (both platforms). Like
    /// `TransportChanged`, never for position progress alone.
    MediaSession {
        state: MediaSessionState,
    },

    Error {
        kind: ErrorKind,
        message: String,
        detail: Option<String>,
    },
    Log {
        level: String,
        target: String,
        message: String,
    },
}

// ---------------------------------------------------------------------------
// Config backup document
// ---------------------------------------------------------------------------

#[typeshare]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct ConfigDocument {
    pub version: u32,
    pub exported_at: EpochMs,
    pub settings: Vec<Setting>,
    pub filters: Vec<Filter>,
    pub shortcuts: Vec<Shortcut>,
    pub servers: Vec<ServerInfo>,
    /// Only present when exported with secrets; encrypted at rest by the platform keystore otherwise.
    pub secrets: Option<HashMap<String, String>>,
    pub audio: AudioSettings,
    pub autoplay: AutoplaySettings,
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub extra: HashMap<String, String>,
}

#[cfg(test)]
mod redaction_tests {
    use super::*;

    #[test]
    fn command_debug_never_shows_the_password_and_kind_is_the_wire_tag() {
        let cmd = Command::AddServer {
            url: "https://music.example/".into(),
            username: "alice".into(),
            password: "hunter2".into(),
            name: None,
        };
        let dbg = format!("{cmd:?}");
        assert!(!dbg.contains("hunter2"), "{dbg}");
        assert!(dbg.contains("<redacted>"), "{dbg}");
        assert_eq!(cmd.kind(), "addServer");
        assert_eq!(Command::Start.kind(), "start");
        // The wire shape is unchanged: a plain string.
        let json = serde_json::to_string(&cmd).unwrap();
        assert!(json.contains(r#""password":"hunter2""#), "{json}");
        let back: Command = serde_json::from_str(&json).unwrap();
        assert_eq!(back, cmd);
    }

    #[test]
    fn media_source_debug_strips_the_query_string() {
        let source = MediaSource {
            key: "k1".into(),
            track: TrackSummary::default(),
            url: "https://music.example/rest/stream?id=t0&u=alice&t=abc123&s=salt".into(),
            headers: [("Authorization".to_string(), "Bearer xyz".to_string())].into(),
            mime_type: None,
            gain_db: 0.0,
            transcoded: false,
            local: false,
        };
        let dbg = format!("{source:?}");
        assert!(dbg.contains("https://music.example/rest/stream"), "{dbg}");
        assert!(
            !dbg.contains("abc123") && !dbg.contains("salt") && !dbg.contains("xyz"),
            "{dbg}"
        );
        let cmd = BackendCommand::Load {
            source,
            next: None,
            position_ms: 0,
            play: true,
        };
        assert!(!format!("{cmd:?}").contains("abc123"));
        assert_eq!(redact_url("file:///tmp/a.flac"), "file:///tmp/a.flac");
        assert_eq!(redact_url("https://h/p#frag"), "https://h/p");
    }
}
